ore 32#define	kAdornFirst 0// signatures#define	kSectionBehavior 'sect'#define	kDialogBehavior 'dlog'#define	kDragDropBehavior 'drag'#define	kClusterBehavior 'club'#define	kFlatBackgroundBehavior 'FLAT'#define	kTabBehavior 'tabb'// Delimiter#define	kNullObject 0#define	kLocalObjectNumber 1#define	kClassIDAndClassname 2#define	kSignatureAndClassname 3// The following are used to set adornments.  Simply add for desired value. #define adnNone 		0b00000000#define adnLineTop		0b00000001#define adnLineLeft 	0b00000010#define adnLineBottom	0b00000100#define adnLineRight	0b00001000#define adnFrame		0b00001111#define adnPatFill		0b00010000#define adnOval 		0b00100000#define adnRRect		0b01000000#define adnShadow		0b10000000#define noAdornment 	adnNone, {1, 1}#define arrowsAndBackspace	0xF0000100#define carriageReturn	0x00002000#define black			{0, 0, 0}#define noInset 		{0, 0, 0, 0}#define stdInset 		{3, 3, 3, 3}#define systemFont		plain,	0, black, ""#define applFont9		plain,	9, black, "a"#define applFont12		plain, 12, black, "a"#define IncludeViews	noID, {0, 0}, {0, 0}, 0, 0, 0, 0, Include#define IncludeViewsAt	noID, {0, 0}, {0, 0}, 0, 0, 0, 0, IncludeAt#define kNoResource 	-1#define kSBarSizeMinus1 15#define MAThreeOh		MAThreeOhView {}#define MARelease13		MARelease13View {}//-------------------------------------behavior----------------------------------#define TBEHAVIORDATA															\	/* fEnabled			*/					byte	notEnabled, enabled;		\  	/* fIdleFreq		*/					longint noIdle = kMaxIdleTime//-------------------------------------button------------------------------------#define TBUTTONDATA_THREEOH													 	\	/* Button label STR# rsrc ID */ integer;									\	/* index into STR# rsrc ID */	integer//-------------------------------------control-----------------------------------#define TCONTROLDATA_THREEOH													\	/* fDefChoice		*/		unsigned longint	mNoHit, mOKHit, mCancelHit,	\				mButtonHit, mCheckBoxHit, 