---------------------#define TVIEWDATA_THREEOH														\		VPOINT;							/* Location inside parent view */		\		VPOINT;							/* Size of view */						\																				\		unsigned bitstring[8]			/* Vertical view determiner */			\					sizeSuperView,		/* View is the same size as superview */\					sizeRelSuperView,	/* Size is relative to the superview */	\					sizePage,			/* View to be the size of one page */	\					sizeFillPages,		/* View fills an exact # of pages */	\					sizeVariable,		/* Size criteria is app-specific */		\					sizeFixed;			/* No default handling of size */		\																				\		unsigned bitstring[8]			/* Horizontal view determiner */		\					sizeSuperView,		/* View is the same size as superview */\					sizeRelSuperView,	/* Size is relative to the superview */	\					sizePage,			/* View to be the size of one page */	\					sizeFillPages,		/* View fills an exact # of pages */	\					sizeVariable,		/* Size criteria is app-specific */		\					sizeFixed;			/* No default handling of size */		\																				\		unsigned byte 	notShown, shown;										\		unsigned byte 	doesntWantToBeTarget, wantsToBeTarget;					\																				\		unsigned byte 	doesntHandleCursor, handlesCursor;						\		unsigned byte 	doesntLetSubViewsHandleCursor, letsSubViewsHandleCursor;\		integer			noCursorID = kNoResource;	/* cursorID */				\																				\		unsigned byte 	doesntHandleHelp, handlesHelp;							\		unsigned byte 	doesntLetSubViewsHandleHelp, letsSubViewsHandleHelp;	\		integer			noHelpID = kNoResource;		/* helpID */				\		integer;						/* help index */						\																				\StartOfDrawingEnvironment:														\		switch {						/* drawing environment */				\			case NoDrawingEnvironment:											\				key integer = kNullObject;										\																				\			case DrawingEnvironmentLocalObject:									\				key integer = kLocalObjectNumber;								\				longint;														\																				\			case DrawingEnvironmentClassIDAndClassname:							\				key integer = kClassIDAndClassname;								\  				longint;								/* class id */			\				longint = ((EndOfDrawingEnvironment[$$ArrayIndex(ViewArray)] - StartOfDrawingEnvironment[$$ArrayIndex(ViewArray)]) / 8) - 6;	\				pstring DrawingEnvironment = "TDRAWINGENVIRONMENT";				\				TDRAWINGENVIRONMENTDATA;										\																				\			case DrawingEnvironmentSignatureAndClassname:						\				key integer = kSignatureAndClassname;							\				literal longint NoIdentifier = kNoIdentifier;/* signature */	\				longint = ((EndOfDrawingEnvironment[$$ArrayIndex(ViewArray)] - StartOfDrawingEnvironment[$$ArrayIndex(ViewArray)]) / 8) - 6;	\				pstring;														\				TDRAWINGENVIRONMENTDATA;										\		};																		\EndOfDrawingEnvironment:														\																				\StartOfAdorners:																\		switch {						/* adorner list */						\			case NoAdorners:													\				key integer = kNullObject;										\																				\			case AdornerListLocalObject:										\				key integer = kLocalObjectNumber;								\				longint;														\																				\			case AdornerListClassIDAndClassname:								\				key integer = kClassIDAndClassname;								\  				longint;								/* class id */			\ClassIDAdornersSize:	longint = ((EndOfAdorners[$$ArrayIndex(ViewArray)] - StartOfAdorners[$$ArrayIndex(ViewArray)]) / 8) - 6;\				hex string[$$Long(ClassIDAdornersSize[$$ArrayIndex(ViewArray)]) - 4];	\																				\			case AdornerListSignatureAndClassname:								\				key integer = kSignatureAndClassname;							\				literal longint NoIdentifier = kNoIdentifier;/* signature */	\				longint = ((EndOfAdorners[$$ArrayIndex(ViewArray)] - StartOfAdorners[$$ArrayIndex(ViewArray)]) / 8) - 6;\				pstring AdornerList = "TADORNERLIST";							\				integer AdornerElementSize = 6;		/* element size */			\				integer AdornerElementSizeShift = 3;/* element size shift */	\				longint DynamicArrayAllocationIncrement = 6;	/* allocation increment */	\				longint = $$CountOf(AdornerElementArray);	/* number of adorners */\				wide array AdornerElementArray {								\					unsigned byte	AdornLast = kAdornLast,						\									AdornAfter = kAdornAfter,					\									DrawView = kDrawView,						\									AdornBefore = kAdornBefore,					\									AdornFirst = kAdornFirst;					\StartOfEachAdorner:																\					switch {						/* each adorner */			\						case AdornerLocalObject:								\							key integer = kLocalObjectNumber;					\							longint	DimAdorner = 1,								\									DrawAdorner = 2,							\									EraseAdorner = 3,							\									HiliteAdorner = 4,							\									PrintAdorner = 5,							\									ResizeIconAdorner = 6,						\									SelectionAdorner = 7;						\																				\						case AdornerClassIDAndClassname:						\							key integer = kClassIDAndClassname;					\							longint;				/* class id */				\ClassIDEachAdornerSize:		longint = ((EndOfEachAdorner[$$ArrayIndex(ViewArray), $$ArrayIndex(AdornerElementArray)] - StartOfEachAdorner[$$ArrayIndex(ViewArray), $$ArrayIndex(AdornerElementArray)]) / 8) - 6;\							hex string[$$Long(ClassIDEachAdornerSize[$$ArrayIndex(ViewArray), $$ArrayIndex(AdornerElementArray)]) - 4];	\																				\						case AdornerSignatureAndClassname:						\							key integer = kSignatureAndClassname;				\							literal longint NoIdentifier = kNoIdentifier;/* signature */	\SignatureEachAdornerSize:	longint = ((EndOfEachAdorner[$$ArrayIndex(ViewArray), $$ArrayIndex(AdornerElementArray)] - StartOfEachAdorner[$$ArrayIndex(ViewArray), $$ArrayIndex(AdornerElementArray)]) / 8) - 6;\							pstring CompatibilityAdorner = "TCOMPATIBILITYADORNER";			\							literal longint NoIdentifier = kNoIdentifier;/* signature */	\							unsigned byte 	dontFreeOnDeletion, freeOnDeletion;	\DataEachAdornerSize:		hex string[$$Long(SignatureEachAdornerSize[$$ArrayIndex(ViewArray), $$ArrayIndex(Adorne